{
  "decline_reason": "",
  "claims": [
    {
      "text": "Advertising alone is not enough: the Manual states that advertising goods not immediately available for sale does not constitute use within the meaning of the Act.",
      "quotes": [
        {
          "ref": "TMM/Part19A/3/3/2~1",
          "quote": "Use of a trade mark in advertising must be concurrent with the placing of the goods or services on the market. Advertisement where the goods/services are not immediately available for sale does not constitute use within the meaning of the Act"
        }
      ],
      "authority": "manual"
    },
    {
      "text": "This differs from goods being available but not yet sold: the Manual says a genuine offering for sale can suffice without an actual sale.",
      "quotes": [
        {
          "ref": "TMM/Part19A/3/3/2~1",
          "quote": "It is not necessary for goods or services to have actually been sold for use ‘in the course of trade’ to have occurred. The offering for sale of goods or services, if genuine, will suffice."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Advertising can nevertheless be relevant to establishing an objective commitment to use the trade mark.",
      "quotes": [
        {
          "ref": "TMM/Part19A/3/3/2~1",
          "quote": "However, it is important to note that while advertising by itself will not constitute an offer for sale, it will be relevant in determining an objective commitment to use (see 3.3 below)."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual recognises a separate route to use in the course of trade through preparatory steps demonstrating an objective commitment to use, going beyond mere investigation or planning even before goods are offered for sale.",
      "quotes": [
        {
          "ref": "TMM/Part19A/3#1",
          "quote": "use through an intention to offer the goods and/or services which is manifested through preparatory steps showing an objective commitment to using the trade mark"
        },
        {
          "ref": "TMM/Part19A/3/3/3~1",
          "quote": "This third category of use ‘in the course of trade’ encompasses situations where an owner has not dealt in goods or services or offered them for sale as at the priority date of the application, but has gone beyond mere preliminary activities."
        },
        {
          "ref": "TMM/Part19A/3/3/3~1",
          "quote": "…the owner will not use its mark unless it has so acted to show that it has gone beyond investigating whether to use the mark and beyond planning to use the mark and has got to the stage where it can be seen objectively to have committed itself to using the mark, that is, to carrying its intention to use the mark into effect."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Whether that objective commitment exists depends on all relevant circumstances, and may be difficult to establish if the goods are not subsequently sold or offered for sale.",
      "quotes": [
        {
          "ref": "TMM/Part19A/3/3/3~2",
          "quote": "Whether an objective commitment has been demonstrated will depend on all the relevant circumstances. A case for objective commitment to use the mark at a particular date may also be difficult to establish where the person claiming use has not subsequently sold or offered for sale the goods or services in question (see Woolly Bull Enterprises Pty Ltd v Reynolds [2001] FCA 261)."
        }
      ],
      "authority": "manual"
    }
  ],
  "declined": false,
  "concepts_used": [
    "GC-0081",
    "GC-0072",
    "GC-0011",
    "GC-0016"
  ]
}
